namespace docking.widgets.table.columnfilter;








using docking.widgets.table;

public class TestTableModel : AbstractTableModel, RowObjectTableModel<Integer> {

	private List<ColumnTestData<object>> columns = new();
	private int rowCount = 0;

	private List<TableModelListener> listeners = new();

	public void addColumn<T>(string name, T[] columnValues) {
		columns.add(new(name, columnValues));
		rowCount = Math.max(rowCount, columnValues.length);
	}

	public void removeColumn(string name) {
		foreach (ColumnTestData<object> c in columns) {
			if (name.equals(c.getName())) {
				columns.remove(c);
				break;
			}
		}
		fireTableDataChanged();
	}

	/* @Override */
	public int getRowCount() {
		return rowCount;
	}

	/* @Override */
	public string getName() {
		return "Test Model";
	}

	/* @Override */
	public int getColumnCount() {
		return columns.size();
	}

	/* @Override */
	public string getColumnName(int columnIndex) {
		return columns.get(columnIndex).getName();
	}

	/* @Override */
	public Class<object> getColumnClass(int columnIndex) {
		return columns.get(columnIndex).getValue(0).GetType();
	}

	/* @Override */
	public bool isCellEditable(int rowIndex, int columnIndex) {
		return false;
	}

	/* @Override */
	public object getValueAt(int rowIndex, int columnIndex) {
		ColumnTestData<object> columnData = columns.get(columnIndex);
		return columnData.getValue(rowIndex);
	}

	/* @Override */
	public void setValueAt(object aValue, int rowIndex, int columnIndex) {
		// unsupported
	}

	/* @Override */
	public void addTableModelListener(TableModelListener l) {
		listeners.add(l);
	}

	/* @Override */
	public void removeTableModelListener(TableModelListener l) {
		listeners.remove(l);
	}

	/* @Override */
	public Integer getRowObject(int viewRow) {
		return viewRow;
	}

	/* @Override */
	public int getRowIndex(Integer t) {
		return t;
	}

	/* @Override */
	public List<Integer> getModelData() {
		List<Integer> rowObjects = new();
		for (int i = 0; i < rowCount; i++) {
			rowObjects.add(i);
		}
		return rowObjects;
	}

	/* @Override */
	public object getColumnValueForRow(Integer t, int columnIndex) {
		return getValueAt(t, columnIndex);
	}

	/* @Override */
	public void fireTableDataChanged() {
		TableModelEvent @event = new TableModelEvent(this);
		foreach (TableModelListener listener in listeners) {
			listener.tableChanged(@event);
		}
	}

	static class ColumnTestData<T> {
		private string name;
		private T[] values;

		public ColumnTestData(string name, T[] columnValues) {
			this.name = name;
			this.values = columnValues;
		}

		public string getName() {
